$insert=static function(string $table,array $data,bool $published=true)use($db,$uuid):int {
    $row=(object)(['uuid'=>$uuid()]+$data+($published?['published'=>1]:[]));
    $db->insertObject('#__joomleague_'.$table,$row,'id'); return (int)$row->id;
};
$batch=static function(string $table,array $rows)use($db):void {
    if(!$rows)return;
    $query=$db->getQuery(true)->insert($db->quoteName('#__joomleague_'.$table))->columns($db->quoteName(array_keys($rows[0])));
    foreach($rows as $row)$query->values(implode(',',array_map(static fn($v)=>$v===null?'NULL':$db->quote((string)$v),array_values($row))));
    $db->setQuery($query)->execute();
};
$club=$insert('club',['id'=>9001,'name'=>'R5 large history']);
$team=(int)$db->setQuery('SELECT team_id FROM #__joomleague_project_entry WHERE id='.(int)$a['entries'][0])->loadResult();
