$db->setQuery('DELETE FROM #__joomleague_project_entry_member WHERE entry_id='.(int)$a['entries'][0])->execute();
$version=(int)$db->setQuery('SELECT profile_version_id FROM #__joomleague_project WHERE id='.(int)$a['id'])->loadResult();
