    if(count($rows)===250){$batch('person',$rows);$rows=[];}
}
$batch('person',$rows); $rows=[];
for($i=0;$i<1205;$i++)$rows[]=['uuid'=>$uuid(),'entry_id'=>$a['entries'][0],'person_id'=>900000+$i,'member_person_type'=>$i<2?'staff':'player','role_code'=>$i<2?$coachRole:'player','valid_from'=>'2020-01-01','published'=>1];
foreach(array_chunk($rows,250)as$chunk)$batch('project_entry_member',$chunk); unset($rows);
for($m=0;$m<60;$m++) {
    $match=$insert('project_match',['project_id'=>$a['id'],'stage_id'=>$a['stage'],'round_id'=>$a['round'],'scheduled_start'=>sprintf('2026-%02d-%02d 12:00:00',1+intdiv($m,28),1+$m%28)]);
    $home=$insert('match_participant',['match_id'=>$match,'project_id'=>$a['id'],'project_entry_id'=>$a['entries'][0],'slot_number'=>1]);
    $away=$insert('match_participant',['match_id'=>$match,'project_id'=>$a['id'],'project_entry_id'=>$a['entries'][1],'slot_number'=>2]);
    $insert('match_result',['match_id'=>$match,'result_type'=>'score','status_code'=>'final'],false);
    $segment=$insert('match_score_segment',['match_id'=>$match,'level_code'=>'result','sequence_number'=>1],false);
    $insert('match_score_value',['match_id'=>$match,'segment_id'=>$segment,'participant_id'=>$home,'numeric_value'=>$m%3===0?1:($m%3===1?2:0)],false);
    $insert('match_score_value',['match_id'=>$match,'segment_id'=>$segment,'participant_id'=>$away,'numeric_value'=>1],false);
    $rows=[];
    for($i=0;$i<1205;$i++) {
        $rows[]=['uuid'=>$uuid(),'match_id'=>$match,'match_participant_id'=>$home,'person_id'=>900000+$i,'member_person_type'=>$i<2?'staff':'player','role_code'=>$i<2?$coachRole:'player','published'=>1];
        if(count($rows)===250){$batch('match_lineup_member',$rows);$rows=[];}
    }
    $batch('match_lineup_member',$rows);
    $insert('match_event',['match_id'=>$match,'project_id'=>$a['id'],'match_participant_id'=>$home,'event_code'=>'goal','event_name_key'=>'R5 goal','sequence_number'=>1,'primary_person_id'=>900002,'primary_name_snapshot'=>'History Person00002','profile_metadata_json'=>'{"statistic_code":"goals"}']);
}
$reader=new Joomleague\Component\Joomleague\Domain\Service\ClubPersonHistoryReader($db);
$data=$reader->read($club,[],[1]);
$assert(count($data['people'])===25 && $data['pagination_state']['total']===1205,'Person page was not bounded');
$assert($data['people'][0]['appearances']===60,'Appearances incorrect');
$assert($data['people'][0]['manager_record']['played']===60 && $data['people'][0]['manager_record']['wins']===20 && $data['people'][0]['manager_record']['draws']===20 && $data['people'][0]['manager_record']['losses']===20,'Coach totals incorrect');
$assert($data['people'][0]['manager_record']['matches']===[],'List hydrated detailed matches');
$metric=$reader->read($club,['sort'=>'metric_goals','direction'=>'desc'],[1]);
$assert($metric['people'][0]['person_id']===900002 && $metric['people'][0]['metrics']['goals']===60,'Metric sort/count incorrect');
$last=$reader->read($club,['start'=>99999999],[1]);
$assert($last['pagination_state']['start']===1200 && count($last['people'])===5,'Final page clamp incorrect');
$all=$reader->read($club,['limit'=>0],[1]);
$assert(count($all['people'])===1000 && $all['pagination_state']['all_capped'],'All limit cap failed');unset($all);
$staff=$reader->read($club,['person_type'=>'staff','staff_only'=>true,'manager_id'=>900001,'detail_start'=>25],[1]);
$assert(count($staff['people'])===2 && count($staff['selected_manager']['manager_record']['matches'])===25 && $staff['detail_state']['total']===60 && $staff['detail_state']['start']===25,'Selected manager detail pagination failed');
$search=$reader->read($club,['search'=>'Person00002'],[1]);
$assert($search['pagination_state']['total']===1 && $search['people'][0]['person_id']===900002,'Search failed');
$assert($reader->read($club,['search'=>'Person00004'],[1])['pagination_state']['total']===1,'Empty nickname broke name search');
$eventRow=$db->setQuery('SELECT id,profile_metadata_json FROM #__joomleague_match_event ORDER BY id',0,1)->loadObject();
$originalMetadata=$eventRow->profile_metadata_json;
$eventRow->profile_metadata_json='{"statistic_code":[]}';$db->updateObject('#__joomleague_match_event',$eventRow,'id');
$assert($reader->read($club,['search'=>'Person00002'],[1])['people'][0]['metrics']['goals']===59,'Malformed metric metadata was not ignored');
$eventRow->profile_metadata_json=$originalMetadata;$db->updateObject('#__joomleague_match_event',$eventRow,'id');
foreach(["%' OR 1=1 --",'Person_','%','!']as$needle)$assert($reader->read($club,['search'=>$needle],[1])['pagination_state']['total']===0,'Search literal was interpreted as SQL or wildcard: '.$needle);
$assert($reader->read($club,['sort'=>'unknown; DROP TABLE users','direction'=>'invalid','limit'=>999999],[1])['pagination_state']['limit']===25,'Untrusted pagination/sort was accepted');
$assert($reader->read($club,['person_type'=>'player'],[1])['pagination_state']['total']===1203,'Person type filter failed');
$assert($reader->read($club,['project_id'=>$fixture['projects']['b']['id']],[1])['people']===[],'Project filter crossed scope');
$assert($reader->read($club,['season_id'=>999999],[1])['people']===[],'Season filter failed');
$assert($reader->read($club,['project_type'=>'cup'],[1])['people']===[],'Project type filter failed');
$personRow=(object)['id'=>900002,'access'=>2];$db->updateObject('#__joomleague_person',$personRow,'id');
$hidden=$reader->read($club,['search'=>'Person00002','manager_id'=>900002],[1]);
$assert($hidden['people']===[] && $hidden['metric_labels']===[] && $hidden['selected_manager']===null,'Private person or event metadata leaked');
$personRow->access=1;$db->updateObject('#__joomleague_person',$personRow,'id');
$opponentTeam=(int)$db->setQuery('SELECT team_id FROM #__joomleague_project_entry WHERE id='.(int)$a['entries'][1])->loadResult();
$opponentRow=(object)['id'=>$opponentTeam,'access'=>2];$db->updateObject('#__joomleague_team',$opponentRow,'id');
$assert($reader->read($club,['person_type'=>'staff','staff_only'=>true,'manager_id'=>900000],[1])['selected_manager']===null,'Private opponent exposed in coach detail');
$opponentRow->access=1;$db->updateObject('#__joomleague_team',$opponentRow,'id');
$firstLineup=$db->setQuery('SELECT * FROM #__joomleague_match_lineup_member WHERE person_id=900000 ORDER BY id',0,1)->loadAssoc();
$schedule=$db->setQuery('SELECT id,scheduled_start FROM #__joomleague_project_match WHERE id='.(int)$firstLineup['match_id'])->loadObject();
$originalStart=$schedule->scheduled_start;$schedule->scheduled_start=null;$db->updateObject('#__joomleague_project_match',$schedule,'id',true);
$undated=$reader->read($club,['person_type'=>'staff','staff_only'=>true,'manager_id'=>900000,'detail_start'=>50],[1]);
$assert(count($undated['selected_manager']['manager_record']['matches'])===10 && $undated['selected_manager']['manager_record']['matches'][9]['match_id']===(int)$firstLineup['match_id'],'Undated coach match was not placed last');
$schedule->scheduled_start=$originalStart;$db->updateObject('#__joomleague_project_match',$schedule,'id');
$extraEntry=$insert('project_entry',['project_id'=>$a['id'],'entry_kind'=>'team','team_id'=>$a['spareTeam']]);
$extraParticipant=$insert('match_participant',['match_id'=>$firstLineup['match_id'],'project_id'=>$a['id'],'project_entry_id'=>$extraEntry,'slot_number'=>3]);
$firstRoot=(int)$db->setQuery('SELECT id FROM #__joomleague_match_score_segment WHERE match_id='.(int)$firstLineup['match_id'].' AND parent_id IS NULL')->loadResult();
$extraScore=$insert('match_score_value',['match_id'=>$firstLineup['match_id'],'segment_id'=>$firstRoot,'participant_id'=>$extraParticipant,'numeric_value'=>2],false);
$ambiguous=$reader->read($club,['person_type'=>'staff','staff_only'=>true,'manager_id'=>900000],[1]);
$assert($ambiguous['selected_manager']['manager_record']['played']===59,'Ambiguous coach match was double counted');
$assert($reader->read($club,['search'=>'Person00000'],[1])['people'][0]['appearances']===60,'Duplicate lineup inflated appearances');
$db->setQuery('DELETE FROM #__joomleague_match_score_value WHERE id='.$extraScore)->execute();
$db->setQuery('DELETE FROM #__joomleague_match_participant WHERE id='.$extraParticipant)->execute();
$db->setQuery('DELETE FROM #__joomleague_project_entry WHERE id='.$extraEntry)->execute();
$projectRow=(object)['id'=>$a['id'],'access'=>2]; $db->updateObject('#__joomleague_project',$projectRow,'id');
$assert($reader->read($club,[],[1])['people']===[],'Private project leaked');
$assert($reader->read($club,[],[1,2])['pagination_state']['total']===1205,'Authorized project missing');
$projectRow->access=1; $db->updateObject('#__joomleague_project',$projectRow,'id');
$scores=$db->setQuery('SELECT * FROM #__joomleague_match_score_value WHERE segment_id='.$firstRoot.' ORDER BY participant_id')->loadObjectList();
$homeScore=$scores[0];$awayScore=$scores[1];
$originalHome=$homeScore->numeric_value;$originalAway=$awayScore->numeric_value;
$homeScore->numeric_value='3.125';$awayScore->numeric_value='2.125';
$db->updateObject('#__joomleague_match_score_value',$homeScore,'id',true);$db->updateObject('#__joomleague_match_score_value',$awayScore,'id',true);
$decimal=$reader->read($club,['person_type'=>'staff','staff_only'=>true],[1])['people'][0]['manager_record'];
$assert($decimal['wins']===21 && $decimal['scored']==='62.125' && $decimal['conceded']==='61.125','Decimal score aggregation lost precision');
$copy=$db->setQuery('SELECT * FROM #__joomleague_sport_profile_version WHERE id='.$version)->loadObject();
unset($copy->id);$copy->profile_version='1.0.0-r5-lower';
$profile['match']['score']['higher_is_better']=false;$copy->payload_json=json_encode($profile,JSON_THROW_ON_ERROR);$copy->payload_checksum=hash('sha256',$copy->payload_json);
$db->insertObject('#__joomleague_sport_profile_version',$copy,'id');
$projectRow->profile_version_id=(int)$copy->id;$db->updateObject('#__joomleague_project',$projectRow,'id');
$lower=$reader->read($club,['person_type'=>'staff','staff_only'=>true],[1])['people'][0]['manager_record'];
$assert($lower['wins']===20 && $lower['losses']===21,'Lower-score-wins profile ignored');
$homeScore->result_rank=1;$awayScore->result_rank=2;
$db->updateObject('#__joomleague_match_score_value',$homeScore,'id',true);$db->updateObject('#__joomleague_match_score_value',$awayScore,'id',true);
$rank=$reader->read($club,['person_type'=>'staff','staff_only'=>true],[1])['people'][0]['manager_record'];
$assert($rank['wins']===21 && $rank['losses']===20,'Rank precedence ignored');
$homeScore->result_rank=null;$awayScore->result_rank=null;$homeScore->numeric_value=null;$homeScore->text_value='unavailable';
$db->updateObject('#__joomleague_match_score_value',$homeScore,'id',true);$db->updateObject('#__joomleague_match_score_value',$awayScore,'id',true);
$missing=$reader->read($club,['person_type'=>'staff','staff_only'=>true],[1])['people'][0]['manager_record'];
$assert($missing['played']===59,'Missing result was counted');
$homeScore->numeric_value=$originalHome;$awayScore->numeric_value=$originalAway;$homeScore->text_value=null;
$db->updateObject('#__joomleague_match_score_value',$homeScore,'id',true);$db->updateObject('#__joomleague_match_score_value',$awayScore,'id',true);
$projectRow->profile_version_id=$version;$db->updateObject('#__joomleague_project',$projectRow,'id');
echo 'PASS: 1205 people, 72300 lineups, SQL totals, metric sort, page clamp, all cap, selected coach detail, search and ACL; peak='.memory_get_peak_usage(true)." bytes\n";
